-- Generated by `chainindex dbt` from chains/base.yaml and abis/AerodromeCLFactory.json. Do not edit: change the chain file or ABI and regenerate.
-- DefaultUnstakedFeeChanged(uint24,uint24)
{{ config(
    materialized='view',
    schema='events_base',
    alias='aerodrome_cl_factory__default_unstaked_fee_changed',
    tags=['chains', 'chain_base'],
) }}

select
    toUInt64(8453) as chain_id,
    address,
    block_number,
    block_time,
    block_hash,
    transaction_hash,
    transaction_index,
    log_index,
    inserted_at,
    toUInt32(reinterpretAsUInt256(reverse(unhex(substring(topic1, 3, 64))))) as old_unstaked_fee,
    toUInt32(reinterpretAsUInt256(reverse(unhex(substring(topic2, 3, 64))))) as new_unstaked_fee
from {{ source('chain_base', 'logs') }}
where topic0 = '0xcbca61144322b913ada4febfb591864cad7617559d7ee0d3e29b48eb93fcc78e'
  and address in (select address from {{ ref('base__contracts') }} where contract = 'aerodrome_cl_factory')
  and (block_number, block_hash) not in (
    select block_number, block_hash from {{ source('chain_base', 'orphaned_blocks') }}
  )
